from typing import Dict, Listfrom pathlib import Pathfrom swat_toolkit.io.readers import ReadFileLinefrom swat_toolkit.utils.data_info import DATAParameterfrom swat_toolkit.io.parameters import SWATParamfrom swat_toolkit.utils.logger import Loggerlogger = Logger.get_logger(__name__)class HRUWriter(ReadFileLine):    SOL_FIELD_WIDTH = 11    def __init__(self, hru_file):        super().__init__()        self.hru_file = hru_file        self.lines = self._read_file(hru_file)    def __getitem__(self, i: int) -> str:        return self.lines[i]    def __repr__(self):        return f"HRUWriter(file='{self.hru_file}', lines={len(self.lines)})"    # ==================== Public Methods ====================    def update_param(self, ext_params: List[DATAParameter],                     new_values: Dict[str, float],                     method: str = 'replace'):        ext = Path(self.hru_file).suffix.lower()        for param in ext_params:            value = new_values.get(param.name)            if value is None:                logger.warning(f"Not find any '{param.name}'. Continue.")                continue            _method = getattr(param, 'method', method)            self._update(param, value, ext, method=_method)    def save(self):        with open(self.hru_file, "w", encoding='utf-8') as f:            f.writelines(self.lines)        logger.debug(f"Saved changes to {self.hru_file}")    # ==================== Dispatch ====================    def _update(        self,        param: DATAParameter,        new_value: float,        ext: str,        method: str = 'replace',    ):        if ext == '.sol':            n_layers = self.__count_layers(self.lines[param.line])            for layer in range(n_layers):                self.__update_sol(param, new_value, method=method, layer=layer)        else:            self.__update_hru(param, new_value, method=method)    # ==================== Core Update Methods ====================    def __update_sol(        self,        param: DATAParameter,        new_value: float,        method: str = 'replace',        layer: int = 0    ):        line = self.lines[param.line]        n_layers = self.__count_layers(line)        if layer >= n_layers:            logger.warning(                f"Layer {layer} larger than Layer exist ({n_layers}) "                f"in line {param.line}. continue."            )            return        old_value = self._get_value_sol_layer(line, layer)        value = self._method(method, old_value, new_value)        value = self._min_max_check(param, value)        prefix_end = line.index(':') + 1        col_start = prefix_end + layer * self.SOL_FIELD_WIDTH        col_end = col_start + self.SOL_FIELD_WIDTH        value_str = f"{value:.{param.round}f}".rjust(self.SOL_FIELD_WIDTH)        self.lines[param.line] = line[:col_start] + value_str + line[col_end:]    def __update_hru(        self,        param: DATAParameter,        new_value: float,        method: str = 'replace'    ):        line = self.lines[param.line]        old_value = self._get_value_positional(line, param.start, param.end)        value = self._method(method, old_value, new_value)        value = self._min_max_check(param, value)        field_width = param.end - param.start        value_str = f"{value:.{param.round}f}".rjust(field_width)        self.lines[param.line] = line[:param.start] + value_str + line[param.end:]    # ==================== Calculation Helpers ====================    def _method(self, method: str, old_value: float, value: float) -> float:        if method == 'replace':            return value        elif method == 'relative':            return old_value * (1 + value)        elif method == 'add':            return old_value + value        else:            raise ValueError(f"Method '{method}' not exits, choose: 'replace', 'relative', 'add'.")    def _min_max_check(self, param: DATAParameter, new_value: float) -> float:        return max(param.vmin, min(new_value, param.vmax))    # ==================== Value Parsers ====================    def _get_value_positional(self, line: str, start: int, end: int) -> float:        try:            return float(line[start:end].strip())        except ValueError:            logger.warning(                f"Không thể parse giá trị tại [{start}:{end}] "                f"trong dòng: {line!r}. Trả về 0.0."            )            return 0.0    def _get_value_sol_layer(self, line: str, layer: int) -> float:        try:            prefix_end = line.index(':') + 1            col_start = prefix_end + layer * self.SOL_FIELD_WIDTH            col_end = col_start + self.SOL_FIELD_WIDTH            return float(line[col_start:col_end].strip())        except (ValueError, IndexError) as e:            logger.warning(                f"Không thể parse giá trị SOL layer {layer}: {e}. Trả về 0.0."            )            return 0.0    def __count_layers(self, line: str) -> int:        try:            prefix_end = line.index(':') + 1            data_part = line[prefix_end:].rstrip('\n').rstrip()            n = len(data_part) // self.SOL_FIELD_WIDTH            return max(n, 0)        except ValueError:            logger.warning(f"Không tìm thấy dấu ':' trong dòng: {line!r}")            return 0